ionId":"{{ forms.planning_console_result_filter.operationId }}","operationStatus":"{{ forms.planning_console_result_filter.operationStatus }}","demandStatus":"{{ forms.planning_console_result_filter.demandStatus }}","from":"{{ forms.planning_console_result_filter.from }}","to":"{{ forms.planning_console_result_filter.to }}"}},"autoLoad":true},"bom":{"key":"bom","label":"排产控制台·bom","sourceType":"custom","serviceName":"planning","serviceMethod":"getPlanningConsoleData","postData":{"dataset":"bom","filters":{"scenarioId":"{{ forms.planning_console_filter.scenarioId }}","planVersionId":"{{ forms.planning_console_result_filter.planVersionId }}","itemId":"{{ forms.planning_console_result_filter.itemId }}","resourceId":"{{ forms.planning_console_result_filter.resourceId }}","operationId":"{{ forms.planning_console_result_filter.operationId }}","operationStatus":"{{ forms.planning_console_result_filter.operationStatus }}","demandStatus":"{{ forms.planning_console_result_filter.demandStatus }}","from":"{{ forms.planning_console_result_filter.from }}","to":"{{ forms.planning_console_result_filter.to }}"}},"autoLoad":true},"preflightIssues":{"key":"preflightIssues","label":"数据完整性预检","sourceType":"custom","serviceName":"planning","serviceMethod":"preflightSupplyPlanIssues","postData":{"jobType":"supply_plan"},"autoLoad":false},"scenarioOptions":{"key":"scenarioOptions","label":"计划场景选项","sourceType":"custom","serviceName":"planning","serviceMethod":"getPlanningConsoleOptions","postData":{"optionType":"scenario"},"autoLoad":true},"versionOptions":{"key":"versionOptions","label":"计划版本选项","sourceType":"custom","serviceName":"planning","serviceMethod":"listPlanningConsoleVersions","postData":{"scenarioId":"{{ forms.planning_console_filter.scenarioId }}"},"autoLoad":true},"itemOptions":{"key":"itemOptions","label":"物料选项","sourceType":"custom","serviceName":"planning","serviceMethod":"getPlanningConsoleOptions","postData":{"optionType":"item"},"autoLoad":true},"resourceOptions":{"key":"resourceOptions","label":"资源选项","sourceType":"custom","serviceName":"planning","serviceMethod":"getPlanningConsoleOptions","postData":{"optionType":"resource"},"autoLoad":true},"operationOptions":{"key":"operationOptions","label":"工序选项","sourceType":"custom","serviceName":"planning","serviceMethod":"getPlanningConsoleOptions","postData":{"optionType":"operation"},"autoLoad":true},"planningRunStarted":{"key":"planningRunStarted","label":"新建排产运行","sourceType":"custom","serviceName":"planning","serviceMethod":"runSupplyPlan","autoLoad":false},"planningRunCanceled":{"key":"planningRunCanceled","label":"取消排产运行","sourceType":"custom","serviceName":"planning","serviceMethod":"cancelPlanningRun","autoLoad":false},"planningVersionPublished":{"key":"planningVersionPublished","label":"发布计划版本","sourceType":"custom","serviceName":"planning","serviceMethod":"publishPlanVersion","autoLoad":false},"runtimeCapabilities":{"key":"runtimeCapabilities","label":"排产运行能力","sourceType":"custom","serviceName":"planning","serviceMethod":"getRuntimeCapabilities","autoLoad":true}},"apis":{"planningPreflight":{"serviceName":"planning","serviceMethod":"preflightSupplyPlanIssues","method":"POST"},"planningRun":{"serviceName":"planning","serviceMethod":"runSupplyPlan","method":"POST"},"planningCancel":{"serviceName":"planning","serviceMethod":"cancelPlanningRun","method":"POST"},"planningPublish":{"serviceName":"planning","serviceMethod":"publishPlanVersion","method":"POST"}},"scriptPolicy":{"capabilities":["http.execute","form.patch","source.refresh","source.set","message.error","message.success","message.warning"],"context":{"dataSourceKeys":["runtimeCapabilities","summary","versionOptions"],"formBlockIds":["planning_console_filter","planning_console_result_filter"],"searchSourceKeys":[],"gridBlockIds":["planning_console_runs_grid"]}},"blocks":[{"id":"planning_console_filter","kind":"form","formType":"default","title":"排程参数设置","initialValues":{"scenarioId":"","runName":"控制台排产运行","currentDate":"now","solver":"heuristic","constraints":52,"iterationMax":0,"resourceIterationMax":500,"rotateResources":true,"individualPoolResources":false},"schema":{"columns":4,"fields":[{"field":"scenarioId","label":"排产场景","component":"vxe-select","required":true,"optionsSourceKey":"scenarioOptions","optionProps":{"label":"label","value":"id"},"props":{"clearable":true,"filterable":true,"placeholder":"选择排产场景"},"events":{"change":[{"type":"setFormField","blockId":"planning_console_result_filter","field":"planVersionId","value":""},{"type":"refreshDataSources","sourceKeys":["summary","demands","operationPlans","materials","planResources","resourcePlans","problems","constraints","runs","flow","bom","versionOptions"]}]}},{"field":"runName","label":"运行名称","component":"vxe-input","props":{"clearable":true,"placeholder":"控制台排产运行"}},{"field":"currentDate","label":"计划当前时间","component":"vxe-input","props":{"clearable":true,"placeholder":"now 或 ISO 时间"}},{"field":"solver","label":"求解器","component":"vxe-select","props":{"clearable":false},"options":[{"label":"启发式（标准）","value":"heuristic"},{"label":"启发式（备选）","value":"heuristic_2"}]},{"field":"constraints","label":"约束级别","component":"lc-number-input","props":{"min":0,"step":1}},{"field":"iterationMax","label":"计划迭代上限","component":"lc-number-input","props":{"min":0,"step":1}},{"field":"resourceIterationMax","label":"资源迭代上限","component":"lc-number-input","props":{"min":0,"step":1}},{"field":"rotateResources","label":"轮换资源","component":"vxe-switch"},{"field":"individualPoolResources","label":"资源池独立排产","component":"vxe-switch"}],"actions":[]},"materialVersion":"1.0.0"},{"id":"planning_console_result_filter","kind":"searchForm","title":"结果筛选","targetSourceKey":"summary","targetSourceKeys":["summary","demands","operationPlans","materials","planResources","resourcePlans","problems","constraints","runs","flow","bom"],"initialValues":{"planVersionId":"","itemId":"","resourceId":"","operationId":"","operationStatus":"","demandStatus":"","from":"","to":""},"schema":{"columns":4,"fields":[{"field":"planVersionId","label":"计划版本","component":"vxe-select","optionsSourceKey":"versionOptions","optionProps":{"label":"label","value":"id"},"props":{"clearable":true,"filterable":true,"placeholder":"自动选择当前版本"}},{"field":"itemId","label":"物料","component":"vxe-select","optionsSourceKey":"itemOptions","optionProps":{"label":"label","value":"id"},"props":{"clearable":true,"filterable":true,"placeholder":"全部物料"}},{"field":"resourceId","label":"资源","component":"vxe-select","optionsSourceKey":"resourceOptions","optionProps":{"label":"label","value":"id"},"props":{"clearable":true,"filterable":true,"placeholder":"全部资源"}},{"field":"operationId","label":"工序","component":"vxe-select","optionsSourceKey":"operationOptions","optionProps":{"label":"label","value":"id"},"props":{"clearable":true,"filterable":true,"placeholder":"全部工序"}},{"field":"operationStatus","label":"计划单状态","component":"vxe-select","props":{"clearable":true},"options":[{"label":"proposed","value":"proposed"},{"label":"approved","value":"approved"},{"label":"confirmed","value":"confirmed"},{"label":"completed","value":"completed"},{"label":"closed","value":"closed"}]},{"field":"demandStatus","label":"需求状态","component":"vxe-select","props":{"clearable":true},"options":[{"label":"inquiry","value":"inquiry"},{"label":"quote","value":"quote"},{"label":"open","value":"open"},{"label":"closed","value":"closed"},{"label":"canceled","value":"canceled"}]},{"field":"from","label":"开始时间","component":"vxe-input","props":{"clearable":true,"type":"datetime-local"}},{"field":"to","label":"结束时间","component":"vxe-input","props":{"clearable":true,"type":"datetime-local"}}],"actions":[{"code":"submit","label":"应用筛选","type":"submit","status":"primary"},{"code":"reset","label":"重置","type":"reset"}]},"materialVersion":"1.0.0"},{"id":"planning_console_actions","kind":"buttonGroup","align":"left","gap":6,"actions":[{"code":"preflight","label":"数据预检","type":"button","mode":"button","icon":"ri-shield-check-line","permissionCode":"planning.models.manage","script":"async function main() {\n  const filter = this.forms.planning_console_filter || {};\n  const scenarioId = String(filter.scenarioId || \"\").trim();\n  if (!scenarioId) {\n    await this.$message.warning(\"请先选择排产场景。\");\n    return false;\n  }\n  const overrides = {\n    currentdate: String(filter.currentDate || \"now\").trim() || \"now\",\n    \"plan.solver\": String(filter.solver || \"heuristic\").trim() || \"heuristic\",\n    constraints: Number(filter.constraints ?? 52),\n    \"plan.iterationmax\": Number(filter.iterationMax ?? 0),\n    \"plan.resourceiterationmax\": Number(filter.resourceIterationMax ?? 500),\n    \"plan.rotateResources\": filter.rotateResources !== false,\n    \"plan.individualPoolResources\": filter.individualPoolResources === true,\n  };\n  const issues = await this.executeHttp({\n    api: \"planningPreflight\",\n    method: \"POST\",\n    body: { jobType: \"supply_plan\", scenarioId, overrides },\n  });\n  await this.$source.set(\"preflightIssues\", issues);\n  const rows = Array.isArray(issues) ? issues : [];\n  const errorCount = rows.filter((issue) => issue && issue.severity === \"error\").length;\n  const warningCount = rows.filter((issue) => issue && issue.severity === \"warning\").length;\n  if (errorCount > 0) {\n    await this.$message.warning(\"预检完成，发现 \" + errorCount + \" 项错误和 \" + warningCount + \" 项警告。\");\n  } else {\n    await this.$message.success(\"数据完整性预检通过。\");\n  }\n  return issues;\n}"},{"code":"run","label":"开始排产","type":"button","mode":"button","status":"primary","icon":"ri-play-circle-line","permissionCode":"planning.models.manage","script":"async function main() {\n  const filter = this.forms.planning_console_filter || {};\n  const scenarioId = String(filter.scenarioId || \"\").trim();\n  if (!scenarioId) {\n    await this.$message.warning(\"请先选择排产场景。\");\n    return false;\n  }\n  const overrides = {\n    currentdate: String(filter.currentDate || \"now\").trim() || \"now\",\n    \"plan.solver\": String(filter.solver || \"heuristic\").trim() || \"heuristic\",\n    constraints: Number(filter.constraints ?? 52),\n    \"plan.iterationmax\": Number(filter.iterationMax ?? 0),\n    \"plan.resourceiterationmax\": Number(filter.resourceIterationMax ?? 500),\n    \"plan.rotateResources\": filter.rotateResources !== false,\n    \"plan.individualPoolResources\": filter.individualPoolResources === true,\n  };\n\n  const capabilities = this.data.runtimeCapabilities || {};\n  const engine = capabilities.engine || {};\n  const trigger = capabilities.trigger || {};\n  const worker = capabilities.worker || {};\n  if (capabilities.canManage !== true) {\n    await this.$message.error(\"当前用户没有启动排产的权限。\");\n    return false;\n  }\n  if (engine.available !== true) {\n    await this.$message.warning(\"排产引擎当前不可用，请检查 frePPLe 运行配置。\");\n    return false;\n  }\n  if (trigger.configured !== true) {\n    await this.$message.warning(\"后台任务服务当前不可用，请先完成运行配置。\");\n    return false;\n  }\n  if (worker.online !== true) {\n    await this.$message.warning(worker.online === false\n      ? \"Trigger.dev Worker 当前离线，请先启动排产后台任务。\"\n      : \"无法确认 Trigger.dev Worker 在线状态，请检查后台任务服务。\");\n    return false;\n  }\n\n  const result = await this.executeHttp({\n    api: \"planningRun\",\n    method: \"POST\",\n    body: {\n      jobType: \"supply_plan\",\n      scenarioId,\n      name: String(filter.runName || \"\").trim() || \"控制台排产运行\",\n      overrides,\n    },\n  });\n  await this.$source.set(\"planningRunStarted\", result);\n  await this.$source.refresh(\"summary\");\n  await this.$source.refresh(\"runs\");\n  await this.$source.refresh(\"versionOptions\");\n  const versionId = result && result.version && result.version.id ? String(result.version.id) : \"\";\n  if (versionId) {\n    await this.$form.patch(\"planning_console_result_filter\", { planVersionId: versionId });\n    await this.$source.refresh(\"summary\");\n    await this.$source.refresh(\"demands\");\n    await this.$source.refresh(\"operationPlans\");\n    await this.$source.refresh(\"materials\");\n    await this.$source.refresh(\"planResources\");\n    await this.$source.refresh(\"resourcePlans\");\n    await this.$source.refresh(\"problems\");\n    await this.$source.refresh(\"constraints\");\n    await this.$source.refresh(\"flow\");\n    await this.$source.refresh(\"bom\");\n  }\n  await this.$message.success(\"排产任务已提交。\");\n  return result;\n}"},{"code":"cancel","label":"取消运行","type":"button","mode":"button","status":"danger","icon":"ri-stop-circle-line","permissionCode":"planning.models.manage","script":"async function main() {\n  const grid = this.grids.planning_console_runs_grid || {};\n  const run = grid.currentRow || null;\n  if (!run || !run.id) {\n    await this.$message.warning(\"请先在运行记录中选择一条任务。\");\n    return false;\n  }\n  if (![\"queued\", \"running\"].includes(String(run.status || \"\"))) {\n    await this.$message.warning(\"仅排队中或运行中的任务可以取消。\");\n    return false;\n  }\n\n  const result = await this.executeHttp({\n    api: \"planningCancel\",\n    method: \"POST\",\n    body: { runId: run.id },\n  });\n  await this.$source.set(\"planningRunCanceled\", result);\n  await this.$source.refresh(\"summary\");\n  await this.$source.refresh(\"runs\");\n  await this.$source.refresh(\"versionOptions\");\n  await this.$message.success(\"取消请求已提交。\");\n  return result;\n}"},{"code":"publish","label":"发布版本","type":"button","mode":"button","icon":"ri-send-plane-line","permissionCode":"planning.models.manage","script":"async function main() {\n  const filter = this.forms.planning_console_result_filter || {};\n  const summary = this.data.summary || {};\n  const versionId = String(filter.planVersionId || summary.versionId || \"\").trim();\n  if (!versionId) {\n    await this.$message.warning(\"当前没有可发布的计划版本。\");\n    return false;\n  }\n\n  const options = Array.isArray(this.data.versionOptions) ? this.data.versionOptions : [];\n  const selected = options.find((option) => option && option.id === versionId);\n  const versionStatus = String((selected && selected.status) || summary.versionStatus || \"\");\n  if (versionStatus !== \"completed\") {\n    await this.$message.warning(\"仅已完成的计划版本可以发布。\");\n    return false;\n  }\n\n  const result = await this.executeHttp({\n    api: \"planningPublish\",\n    method: \"POST\",\n    body: { id: versionId },\n  });\n  await this.$source.set(\"planningVersionPublished\", result);\n  await this.$source.refresh(\"summary\");\n  await this.$source.refresh(\"demands\");\n  await this.$source.refresh(\"operationPlans\");\n  await this.$source.refresh(\"materials\");\n  await this.$source.refresh(\"planResources\");\n  await this.$source.refresh(\"resourcePlans\");\n  await this.$source.refresh(\"problems\");\n  await this.$source.refresh(\"constraints\");\n  await this.$source.refresh(\"runs\");\n  await this.$source.refresh(\"flow\");\n  await this.$source.refresh(\"bom\");\n  await this.$source.refresh(\"versionOptions\");\n  await this.$message.success(\"计划版本已发布。\");\n  return result;\n}"},{"code":"refresh","label":"刷新","type":"button","mode":"button","icon":"ri-refresh-line","directives":[{"type":"refreshDataSources","sourceKeys":["summary","demands","operationPlans","materials","planResources","resourcePlans","problems","constraints","runs","flow","bom","versionOptions","runtimeCapabilities"]}]}],"materialVersion":"1.0.0"},{"id":"planning_console_runtime_status","kind":"statCard","sourceKey":"runtimeCapabilities","items":[{"label":"控制权限","field":"accessLabel"},{"label":"排产引擎","field":"engineLabel"},{"label":"后台任务","field":"triggerLabel"}],"materialVersion":"1.0.0"},{"id":"planning_console_tabs","kind":"tabs","defaultKey":"overview","tabs":[{"key":"overview","label":"排产总览","blocks":[{"id":"planning_console_stats","kind":"statCard","sourceKey":"summary","items":[{"label":"计划单","field":"operationPlanCount","suffix":"单","formatter":{"type":"number","locale":"zh-CN","emptyText":"